/**
 * Enrollment data loader — the single seam between the app and the enrollment
 * dataset (mirrors policyLoader.js).
 *
 * Source of truth is a build-time snapshot of JHU's enrollment workbook
 * (enrollment-snapshot.json), regenerated by scripts/fetch-enrollment-snapshot.mjs
 * on a schedule / manual trigger in CI. The bundled CSV stays as a fallback: if
 * the snapshot is ever missing or malformed, the app parses the CSV instead of
 * breaking. The CSV also still backs the "Download data (CSV)" affordance, which
 * serves the published source verbatim.
 *
 * The State policies view reads `enrollmentInLatestYear` for its "Homeschoolers"
 * column; the Enrollment view consumes `enrollmentByState` / `enrollmentYears`
 * for everything it renders.
 */

import csvText from "../../homeschool-hub-state-summary-data.csv?raw";
import snapshot from "./enrollment-snapshot.json";
import { parseCsv } from "./parseCsv.js";

// Raw CSV text, exposed for the "Download data (CSV)" affordance.
export const enrollmentCsvText = csvText;

// A snapshot is usable only if it has a non-empty byState map and a years array
// — guards against a truncated or malformed JSON.
function isUsableSnapshot(snap) {
  const states = snap?.byState;
  if (!states || typeof states !== "object") return false;
  if (!Array.isArray(snap.years) || snap.years.length === 0) return false;
  return Object.keys(states).length > 0;
}

// Shaped enrollment data, keyed by full state name. Prefer the live snapshot;
// fall back to the bundled CSV if it's unavailable.
export const { byState: enrollmentByState, years: enrollmentYears } =
  isUsableSnapshot(snapshot)
    ? { byState: snapshot.byState, years: snapshot.years }
    : parseCsv(csvText);

// When the snapshot was pulled (ISO string), or null on CSV fallback. Available
// for surfacing data freshness in the UI.
export const enrollmentGeneratedAt = isUsableSnapshot(snapshot)
  ? snapshot.generatedAt
  : null;

// The most recent complete school year in the dataset (start-year integer).
export const enrollmentLatestYear = enrollmentYears[enrollmentYears.length - 1];

/**
 * A state's enrollment in the latest dataset year, or null if it didn't report
 * that year. The policy view's Homeschoolers column reads a single shared year
 * across all states so its header can name a concrete year honestly; states
 * with no value for that year render as "not reported".
 */
export function enrollmentInLatestYear(name) {
  return enrollmentByState[name]?.[enrollmentLatestYear] ?? null;
}
